import test from "node:test";
import assert from "node:assert/strict";
import { searchRotated } from "./attempt.js";

const todo = searchRotated.toString().includes("TODO");
const skip = todo && "unsolved — edit attempt.js (delete the TODO line) to activate these tests";

test("the classic example", { skip }, () => {
  assert.equal(searchRotated([4, 5, 6, 7, 0, 1, 2], 0), 4);
  assert.equal(searchRotated([4, 5, 6, 7, 0, 1, 2], 3), -1);
});

test("target in the left (larger) half", { skip }, () => {
  assert.equal(searchRotated([4, 5, 6, 7, 0, 1, 2], 6), 2);
  assert.equal(searchRotated([4, 5, 6, 7, 0, 1, 2], 4), 0);
});

test("target in the right (smaller) half", { skip }, () => {
  assert.equal(searchRotated([4, 5, 6, 7, 0, 1, 2], 1), 5);
  assert.equal(searchRotated([4, 5, 6, 7, 0, 1, 2], 2), 6);
});

test("an unrotated array still works", { skip }, () => {
  assert.equal(searchRotated([1, 2, 3, 4, 5], 4), 3);
  assert.equal(searchRotated([1, 2, 3, 4, 5], 6), -1);
});

test("rotated by one, either way", { skip }, () => {
  assert.equal(searchRotated([5, 1, 2, 3, 4], 5), 0);
  assert.equal(searchRotated([2, 3, 4, 5, 1], 1), 4);
});

test("empty and single-element arrays", { skip }, () => {
  assert.equal(searchRotated([], 5), -1);
  assert.equal(searchRotated([1], 1), 0);
  assert.equal(searchRotated([1], 0), -1);
});

test("two elements", { skip }, () => {
  assert.equal(searchRotated([3, 1], 1), 1);
});

/**
 * Search a rotated sorted array — binary search that first works out
 * which half it can trust.
 *
 * Key fact: however you cut a rotated sorted array in two, at most one
 * half can contain the "wrap" where values drop — so the OTHER half is
 * plainly sorted. In a plainly sorted half you can tell instantly
 * whether the target is inside (is it between the two ends?). If it
 * is, search there; if it isn't, search the other half. Either way
 * half the array is discarded, so the cost stays logarithmic.
 *
 * Time: O(log n). Space: O(1).
 *
 * @param {number[]} nums - sorted ascending then rotated; distinct values
 * @param {number} target
 * @returns {number} the index of target, or -1 if it isn't there
 */
export function searchRotated(nums, target) {
  let low = 0;
  let high = nums.length - 1; // -1 for an empty array: the loop never runs

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);

    if (nums[mid] === target) return mid;

    if (nums[low] <= nums[mid]) {
      // The LEFT half [low..mid] is sorted (<= covers a 1-wide half).
      if (nums[low] <= target && target < nums[mid]) {
        high = mid - 1; // inside the sorted half
      } else {
        low = mid + 1; // must be in the messy half, if anywhere
      }
    } else {
      // Otherwise the RIGHT half [mid..high] is the sorted one.
      if (nums[mid] < target && target <= nums[high]) {
        low = mid + 1; // inside the sorted half
      } else {
        high = mid - 1; // must be in the messy half, if anywhere
      }
    }
    // The bounds are asymmetric on purpose: mid was already tested for
    // equality above, so it is excluded; low and high are not.
  }

  return -1; // window emptied — target was never in the array
}

import test from "node:test";
import assert from "node:assert/strict";
import { searchRotated } from "./solution.js";

test("the classic example", () => {
  assert.equal(searchRotated([4, 5, 6, 7, 0, 1, 2], 0), 4);
  assert.equal(searchRotated([4, 5, 6, 7, 0, 1, 2], 3), -1);
});

test("target in the left (larger) half", () => {
  assert.equal(searchRotated([4, 5, 6, 7, 0, 1, 2], 6), 2);
  assert.equal(searchRotated([4, 5, 6, 7, 0, 1, 2], 4), 0);
});

test("target in the right (smaller) half", () => {
  assert.equal(searchRotated([4, 5, 6, 7, 0, 1, 2], 1), 5);
  assert.equal(searchRotated([4, 5, 6, 7, 0, 1, 2], 2), 6);
});

test("an unrotated array still works", () => {
  assert.equal(searchRotated([1, 2, 3, 4, 5], 4), 3);
  assert.equal(searchRotated([1, 2, 3, 4, 5], 6), -1);
});

test("rotated by one, either way", () => {
  assert.equal(searchRotated([5, 1, 2, 3, 4], 5), 0);
  assert.equal(searchRotated([2, 3, 4, 5, 1], 1), 4);
});

test("empty and single-element arrays", () => {
  assert.equal(searchRotated([], 5), -1);
  assert.equal(searchRotated([1], 1), 0);
  assert.equal(searchRotated([1], 0), -1);
});

test("two elements", () => {
  assert.equal(searchRotated([3, 1], 1), 1);
});
